  <template class="dream-big-discuss-ui__source">$1</template>
  <details class="dream-big-discuss-ui__panel" open>
    <summary class="dream-big-discuss-ui__summary">
      <span class="dream-big-discuss-ui__summary-title">梦境大讨论</span>
      <span class="dream-big-discuss-ui__summary-meta"></span>
    </summary>
    <div class="dream-big-discuss-ui__content">
